#include "coh_power_sets.h"
#include "../stash32/coh_stash32.h"
#include <string.h>
#include "power_set_schema.inc"
typedef struct{const void*p;size_t n;}Span;
typedef struct{CohBytes input;size_t at;CohStatus status;}Parse;
static int valid(Span a){return a.p?(uintptr_t)a.p<=UINTPTR_MAX-a.n:!a.n;}
static int overlap(Span a,Span b){return a.n&&b.n&&(uintptr_t)a.p<(uintptr_t)b.p+b.n&&(uintptr_t)b.p<(uintptr_t)a.p+a.n;}
static void need(Parse*p,int yes,CohStatus s){if(p->status==COH_OK&&!yes)p->status=s;}
static const uint8_t*bytes(Parse*p,size_t n){if(p->status!=COH_OK)return NULL;if(n>p->input.size-p->at){p->status=COH_INVALID;return NULL;}const uint8_t*b=p->input.data+p->at;p->at+=n;return b;}
static uint32_t word(Parse*p){const uint8_t*b=bytes(p,4);return b?((uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24):0;}
static size_t segment(Parse*p){uint32_t n=word(p);need(p,n<=p->input.size-p->at,COH_INVALID);return p->status==COH_OK?p->at+n:p->at;}
static CohBytes text(Parse*p){CohBytes out={0};const uint8_t*b=bytes(p,2);if(!b)return out;size_t n=(size_t)b[0]|(size_t)b[1]<<8;need(p,n<260,COH_LIMIT);if(p->status!=COH_OK)return out;b=bytes(p,n);if(!b)return out;need(p,memchr(b,0,n)==NULL,COH_INVALID);out=(CohBytes){b,n};(void)bytes(p,(4-(n+2)%4)%4);return out;}
static int literal(CohBytes a,const char*b){size_t n=strlen(b);return a.size==n&&!memcmp(a.data,b,n);}
static unsigned fold(unsigned c){return c>='A'&&c<='Z'?c+32:c;}
static int equal(CohBytes a,CohBytes b){if(a.size!=b.size)return 0;for(size_t i=0;i<a.size;i++)if(fold(a.data[i])!=fold(b.data[i]))return 0;return 1;}
/* Parsed immutable field spans and strings were validated once on admission;
 * lookups do constant-time bounds extraction, never repeat a key validation. */
static CohStatus name(const CohPowerSetDictionary*d,uint32_t index,CohBytes*out){if(index>=d->count)return COH_STATE;CohPowerSetSpan s=d->entries[index].full_name;if(s.begin>s.end||s.end>d->input.size||s.end-s.begin<4)return COH_STATE;const uint8_t*p=d->input.data+s.begin;size_t n=(size_t)p[0]|(size_t)p[1]<<8;if(n>=260||n+2+(4-(n+2)%4)%4!=s.end-s.begin)return COH_STATE;*out=(CohBytes){p+2,n};return COH_OK;}
static CohStatus insert(CohPowerSetDictionary*d,uint32_t index,size_t*work){CohBytes key;CohStatus status=name(d,index,&key);if(status!=COH_OK)return status;uint32_t hash;status=coh_stash32_string_hash(key,COH_STASH32_DEFAULT_SEED,&hash);if(status!=COH_OK)return status;uint32_t slot=hash&(d->index_slots-1),probe=1;for(unsigned i=0;i<COH_STASH32_SLOT_MAX;i++){if(!*work)return COH_LIMIT;(*work)--;uint32_t prior=d->slots[slot];if(!prior){d->slots[slot]=index+1;d->unique_count++;return COH_OK;}CohBytes other;status=name(d,prior-1,&other);if(status!=COH_OK)return status;size_t cost=1+(key.size==other.size?key.size:0);if(cost>*work)return COH_LIMIT;*work-=cost;if(equal(key,other)){d->duplicate_count++;return COH_OK;}slot=(slot+probe*probe)&(d->index_slots-1);probe++;}return COH_LIMIT;}
CohStatus coh_power_sets_read(CohBytes input,uint64_t lease,const uint8_t expected[32],const CohCostumeImportDigest*d,CohPowerSetDictionary*out,CohPowerSetWorkspace*w,size_t budget,size_t retained){
 if(!input.data||!input.size||input.size>COH_POWER_SET_INPUT_MAX||!lease||!expected||!d||!d->sha256||!out||!w||(!d->context&&d->context_bytes)||(d->context&&!d->context_bytes)||!budget||budget>COH_POWER_SET_RAM_MAX)return COH_INVALID;
 Span spans[]={{input.data,input.size},{expected,32},{d,sizeof(*d)},{out,sizeof(*out)},{w,sizeof(*w)},{d->context,d->context_bytes}};size_t charge=COH_POWER_SET_STACK_RESERVE;
 for(unsigned i=0;i<6;i++){if(!valid(spans[i]))return COH_INVALID;for(unsigned j=0;j<i;j++)if(overlap(spans[i],spans[j]))return COH_INVALID;if(spans[i].n>budget||charge>budget-spans[i].n)return COH_LIMIT;charge+=spans[i].n;}
 if(d->scratch_reserve>budget-charge)return COH_LIMIT;
 charge+=d->scratch_reserve;if(retained>budget-charge)return COH_LIMIT;uint8_t any=0,hash[32];for(unsigned i=0;i<32;i++)any|=expected[i];if(!any)return COH_STATE;
 CohPowerSetDictionary*c=&w->candidate;memset(c,0,sizeof(*c));c->input=input;c->input_lease=lease;Parse p={input,0,COH_OK};const uint8_t*magic=bytes(&p,8);need(&p,magic&&!memcmp(magic,"CrypticS",8),COH_INVALID);c->schema_crc=word(&p);need(&p,c->schema_crc==UINT32_C(0x2fe0d52d),COH_STATE);CohBytes signature=text(&p),files=text(&p);need(&p,literal(signature,"Parse6")&&literal(files,"Files1"),COH_UNSUPPORTED);size_t files_end=segment(&p);c->dependency_count=word(&p);need(&p,c->dependency_count<=4096,COH_LIMIT);for(unsigned i=0;i<c->dependency_count&&p.status==COH_OK;i++){(void)text(&p);(void)word(&p);need(&p,p.at<=files_end,COH_INVALID);}need(&p,p.at==files_end,COH_INVALID);
 size_t root_end=segment(&p);need(&p,root_end==input.size,COH_INVALID);c->count=word(&p);need(&p,c->count<=COH_POWER_SET_MAX,COH_LIMIT);
 for(unsigned i=0;i<c->count&&p.status==COH_OK;i++){size_t begin=p.at,end=segment(&p);c->entries[i].record=(CohPowerSetSpan){(uint32_t)begin,(uint32_t)end};for(unsigned f=0;f<30&&p.status==COH_OK;f++){size_t at=p.at;uint32_t n;switch(field_kinds[f]){case 1:{CohBytes value=text(&p);if(f==1)for(size_t j=0;j<value.size;j++)need(&p,value.data[j]<128,COH_UNSUPPORTED);break;}case 2:n=word(&p);need(&p,n<=65536,COH_LIMIT);if(f==21){need(&p,n<=UINT32_MAX-c->power_name_count,COH_LIMIT);c->power_name_count+=n;}for(unsigned j=0;j<n&&p.status==COH_OK;j++)(void)text(&p);break;case 3:(void)word(&p);break;case 4:n=word(&p);need(&p,n<=65536,COH_LIMIT);if(f==22){need(&p,n<=UINT32_MAX-c->pointer_index_count,COH_LIMIT);c->pointer_index_count+=n;}(void)bytes(&p,(size_t)n*4);break;default:need(&p,0,COH_STATE);break;}if(f==1)c->entries[i].full_name=(CohPowerSetSpan){(uint32_t)at,(uint32_t)p.at};need(&p,p.at<=end,COH_INVALID);}need(&p,p.at==end&&end<=root_end,COH_INVALID);}
 need(&p,p.at==root_end&&p.at==input.size,COH_INVALID);if(p.status!=COH_OK)return p.status;c->index_slots=8;uint32_t optimal=(c->count*3+1)/2;while(c->index_slots<optimal)c->index_slots*=2;size_t work=COH_POWER_SET_WORK_MAX;for(unsigned i=0;i<c->count;i++){CohStatus status=insert(c,i,&work);if(status!=COH_OK)return status;}CohStatus status=d->sha256(d->context,input,hash);if(status!=COH_OK)return status;if(memcmp(hash,expected,32))return COH_STATE;memcpy(c->input_sha256,hash,32);c->raw_schema_validated=c->historical_schema_crc_matched=1;c->source_constructor_accepted=c->duplicate_count==0;*out=*c;return COH_OK;
}
CohStatus coh_power_sets_find(const CohPowerSetDictionary*d,CohBytes key,uint32_t*out){if(!d||!out||!key.data||key.size>=260)return COH_INVALID;Span a={d,sizeof(*d)},b={key.data,key.size},c={out,sizeof(*out)};if(!valid(a)||!valid(b)||!valid(c)||overlap(a,c)||overlap(b,c))return COH_INVALID;if(!d->raw_schema_validated||!d->input_lease||!d->input.data||d->input.size>COH_POWER_SET_INPUT_MAX||d->count>COH_POWER_SET_MAX||d->index_slots<8||d->index_slots>COH_POWER_SET_INDEX_SLOTS||(d->index_slots&(d->index_slots-1)))return COH_STATE;if(!valid((Span){d->input.data,d->input.size})||overlap((Span){d->input.data,d->input.size},c))return COH_INVALID;for(size_t i=0;i<key.size;i++)if(!key.data[i]||key.data[i]>127)return COH_UNSUPPORTED;uint32_t hash;CohStatus status=coh_stash32_string_hash(key,COH_STASH32_DEFAULT_SEED,&hash);if(status!=COH_OK)return status;uint32_t slot=hash&(d->index_slots-1),probe=1;for(unsigned i=0;i<COH_STASH32_SLOT_MAX;i++){uint32_t row=d->slots[slot];if(!row)return COH_NOT_FOUND;CohBytes other;status=name(d,row-1,&other);if(status!=COH_OK)return status;if(equal(key,other)){*out=row-1;return COH_OK;}slot=(slot+probe*probe)&(d->index_slots-1);probe++;}return COH_LIMIT;}

CohStatus coh_power_sets_field(const CohPowerSetDictionary*d,uint32_t which,uint32_t field,CohBytes*out){
 if(!d||!out||field>=30)return COH_INVALID;
 Span a={d,sizeof(*d)},b={out,sizeof(*out)};if(!valid(a)||!valid(b)||overlap(a,b))return COH_INVALID;
 if(!d->raw_schema_validated||!d->input_lease||!d->input.data||d->input.size>COH_POWER_SET_INPUT_MAX||d->count>COH_POWER_SET_MAX||which>=d->count)return COH_STATE;
 Span input={d->input.data,d->input.size};if(!valid(input)||overlap(input,b))return COH_INVALID;CohPowerSetSpan record=d->entries[which].record;if(record.begin>record.end||record.end>d->input.size||record.end-record.begin<4)return COH_STATE;Parse p={d->input,record.begin,COH_OK};size_t end=segment(&p);if(p.status!=COH_OK||end!=record.end)return COH_STATE;for(unsigned f=0;f<=field;f++){size_t begin=p.at;uint32_t n;switch(field_kinds[f]){case 1:(void)text(&p);break;case 2:n=word(&p);need(&p,n<=65536,COH_LIMIT);for(unsigned j=0;j<n&&p.status==COH_OK;j++)(void)text(&p);break;case 3:(void)word(&p);break;case 4:n=word(&p);need(&p,n<=65536,COH_LIMIT);(void)bytes(&p,(size_t)n*4);break;default:need(&p,0,COH_STATE);break;}need(&p,p.at<=end,COH_STATE);if(p.status!=COH_OK)return p.status;if(f==29&&p.at!=end)return COH_STATE;if(f==field){CohBytes value={d->input.data+begin,p.at-begin};*out=value;return COH_OK;}}return COH_STATE;
}
